<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
if (!in_array(strtolower((string)($currentUser['role'] ?? '')), ['superadmin','admin','manager'], true)) { header('Location:index.php'); exit; }
ensureAwardsTables($pdo);$id=(int)($_GET['id']??0);$award=null;foreach(fetchAwards($pdo) as $row)if((int)$row['id']===$id)$award=$row;$award=$award?:['id'=>0,'name'=>'','description_html'=>'','image_asset_id'=>0,'display_order'=>100,'is_published'=>1,'is_archived'=>0];$assets=fetchAssetLibrary($pdo,true);
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim((string)($_POST['name']??''));if($name==='')$alerts[]=['type'=>'danger','message'=>'Award name is required.'];if(!$alerts){$data=[':name'=>$name,':description'=>trim((string)($_POST['description_html']??''))?:null,':asset'=>(int)($_POST['image_asset_id']??0)?:null,':order'=>(int)($_POST['display_order']??100),':published'=>!empty($_POST['is_published'])?1:0,':archived'=>!empty($_POST['is_archived'])?1:0];if($id){$data[':id']=$id;$sql='UPDATE award_catalog SET name=:name,description_html=:description,image_asset_id=:asset,display_order=:order,is_published=:published,is_archived=:archived WHERE id=:id';}else $sql='INSERT INTO award_catalog(name,description_html,image_asset_id,display_order,is_published,is_archived) VALUES(:name,:description,:asset,:order,:published,:archived)';$pdo->prepare($sql)->execute($data);$_SESSION['flash_success']='Award saved.';header('Location:awards.php');exit;}$award=array_merge($award,$_POST);}
admin_layout_start($id?'Edit Award':'Add Award','awards');
?><div class="d-flex justify-content-between align-items-center mb-3"><div><div class="small text-muted">Awards</div><h5 class="mb-0"><?php echo $id?'Edit award':'Add award'; ?></h5></div><a class="btn btn-outline-secondary" href="awards.php">Back to Awards</a></div><div class="card-soft p-4"><form method="post" class="row g-3"><div class="col-md-6"><label class="form-label">Award name</label><input class="form-control" name="name" required value="<?php echo h($award['name']); ?>"></div><div class="col-md-3"><label class="form-label">Order</label><input class="form-control" type="number" name="display_order" value="<?php echo (int)$award['display_order']; ?>"></div><div class="col-md-3"><label class="form-label">Image</label><select class="form-select" name="image_asset_id"><option value="0">Holding image</option><?php foreach($assets as $asset):if(($asset['asset_type']??'')!=='image')continue;?><option value="<?php echo (int)$asset['id']; ?>" <?php echo (int)$award['image_asset_id']===(int)$asset['id']?'selected':''; ?>><?php echo h($asset['title']?:$asset['name']); ?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control wysiwyg-field" name="description_html" rows="10"><?php echo h($award['description_html']); ?></textarea></div><div class="col-12"><label class="me-3"><input type="checkbox" name="is_published" <?php echo !empty($award['is_published'])?'checked':''; ?>> Published</label><label><input type="checkbox" name="is_archived" <?php echo !empty($award['is_archived'])?'checked':''; ?>> Archived</label></div><div><button class="btn btn-success">Save award</button> <a class="btn btn-outline-secondary" href="awards.php">Cancel</a></div></form></div><?php render_tinymce_bootstrap(); ?><script>if(window.tinymce)tinymce.init(window.ildraTinyMceConfig({selector:'textarea.wysiwyg-field'}));</script><?php admin_layout_end();
